if(cityHappy>.55||(typeof devSkylineBypass516B==='function'&&devSkylineBypass516B())){
  const mgDone=new Uint8Array(N*N);
  // T341h 巨廈直接成形（先於塔掃描＝街心大簇優先長大的，塔撿剩下的 2×2）：
  // 3×3 同類分區簇，實質 Lv2+ 供電無火 ≥5/9，其餘格可為公園（吸收＝空中花園，成對撤 COV 印）
  // 或同類空地塊/空草地；碰到路/他樓即不合格（路不可吞）。幸福>0.6、需求>0.25，每簇每天 2%。
  // 為何不做「塔進化」：實測塔恆貼路而生（分區沿路長），3×3 環永缺一格路＝結構性死路（T341-DIAG 900 天凍結）。
  if(cityHappy>.6||(typeof devSkylineBypass516B==='function'&&devSkylineBypass516B())){
    for(let y=0;y<N-2;y++)for(let x=0;x<N-2;x++){
      const i0=idx(x,y);
      if(mgDone[i0])continue;
      let kk=0; /* T342e⬚種子改「窗內任一 Lv2+」定類——原「左上角必為 Lv2+」漏掃大量合格窗（左上是公園/空地/L1 即盲區） */
      for(let dy=0;dy<3&&!kk;dy++)for(let dx=0;dx<3;dx++){const qb0=tiles[idx(x+dx,y+dy)].bld;if(qb0&&!qb0.ref&&(qb0.k===1||qb0.k===2)&&(qb0.lv>=2||(typeof devSkylineBypass516B==='function'&&devSkylineBypass516B()))){kk=qb0.k;break;}}
      if(!kk||(dem[kk]<=.25&&!(typeof devSkylineBypass516B==='function'&&devSkylineBypass516B())))continue;
      let ok2=true,subst=0;const parks341=[];
      for(let dy=0;dy<3&&ok2;dy++)for(let dx=0;dx<3;dx++){
        const qi=idx(x+dx,y+dy);
        if(mgDone[qi]){ok2=false;break;}
        const qt=tiles[qi],qb=qt.bld;
        if(qb&&!qb.ref&&qb.k===kk&&(qb.lv>=2||(typeof devSkylineBypass516B==='function'&&devSkylineBypass516B()))&&qb.pw&&qb.wa&&(!sewNeed442||SEW_OK442[qi])&&!qb.fire){subst++;continue;} /* T442：巨廈核心至少5/9棟需電+水+集中污水，基礎設施先於垂直密度 */
        if(qb&&!qb.ref&&qb.k===kk&&qb.lv===1&&!qb.fire)continue; /* T342d：同類 Lv1 舊屋可吸收（都更敘事；實測 L1 遍地＝3×3 永不合格的真兇） */
        if(qb&&!qb.ref&&qb.k===4){parks341.push([x+dx,y+dy]);continue;}
        if(!qb&&!qt.road&&!qt.ruin&&(qt.zone===kk||(!qt.zone&&qt.t===2)))continue;
        ok2=false;break;
      }
      if(!ok2||subst<5)continue;
      for(let dy=0;dy<3;dy++)for(let dx=0;dx<3;dx++)mgDone[idx(x+dx,y+dy)]=1; /* T342c⬚合格即劃「大型開發預定地」——擲髀失敗也不讓後續塔掃描吃碎同一簇（實測塔多窗口 8%/日 撞贏巨廈單窗 4%，磎片化）；mgDone 每 tick 重建，預定地每日重新資格 */
      if((typeof devSkylineBypass516B==='function'&&devSkylineBypass516B())||R()<.04){ /* T342b: .02→.04 */
        const mk2=kk===1?105:106;
        for(const[px2,py2]of parks341)stampCov('park',px2,py2,COVR.park,-1); // 成對撤印（Uint8 鐵律）
        for(let dy=0;dy<3;dy++)for(let dx=0;dx<3;dx++){
          const j2=idx(x+dx,y+dy);
          mgDone[j2]=1;const jt=T(j2);jt.zone=0;
          jt.bld=(dx===0&&dy===0)?{k:mk2,lv:1,v:0,age:0,pw:true,wa:true,h:1,sz:3}:{k:mk2,ref:[x,y]};
        }
        markLandDirty(x+1,y+1,8);
        toast((mk2===105?'🌆 住宅巨廈拔地而起！（居民 '+MEGA_POP+' 人）':'🌆 商業綜合體開幕！（就業 '+MEGA_JOBS+'）'),'gold',x,y);sFanfare();
      }
    }
  } // 本輪已合併/佔用格，避免相鄰候選重疊消耗同一格
  for(let y=0;y<N-1;y++)for(let x=0;x<N-1;x++){
    const i0=idx(x,y);
    if(mgDone[i0])continue;
    const b0=tiles[i0].bld;
    if(!b0||b0.ref||(b0.k!==1&&b0.k!==2)||(b0.lv<2&&!(typeof devSkylineBypass516B==='function'&&devSkylineBypass516B())))continue; /* T341c⬚種子同步放寬 Lv2+（原只改了四格檢查漏了種子） */
    const kk=b0.k;
    if(dem[kk]<=.3&&!(typeof devSkylineBypass516B==='function'&&devSkylineBypass516B()))continue; /* T341c：地價閘撤除——實測供水簇全在低地價邊緣(56-87)、高地價中心無水＝閘門成空集；稀缺性由供水+密度承擔 */
    const quad=[[x,y],[x+1,y],[x,y+1],[x+1,y+1]];
    let ok=true;
    for(const[qx,qy]of quad){
      const qi=idx(qx,qy);
      if(mgDone[qi]){ok=false;break;}
      const qb=tiles[qi].bld;
      if(!qb||qb.ref||qb.k!==kk||(qb.lv<2&&!(typeof devSkylineBypass516B==='function'&&devSkylineBypass516B()))||!qb.pw||!qb.wa||(sewNeed442&&!SEW_OK442[qi])||qb.fire){ok=false;break;} /* T442：摩天樓候選也需污水接管；T341b：Lv3→Lv2+（實測 700 天 5363 人城僅 4 棟 Lv3、0 合格簇＝鎖鏈餃死；改由高地價閘門承擔稀缺性） */
    }
    if(!ok)continue;
    if((typeof devSkylineBypass516B==='function'&&devSkylineBypass516B())||R()<.02){ // T127：每合格 2×2 簇每天 2% 機率合併
      for(const[qx,qy]of quad)mgDone[idx(qx,qy)]=1;
      const tk=kk===1?33:34;
      for(const[qx,qy]of quad){
        const qt=T(idx(qx,qy));
        qt.bld=(qx===x&&qy===y)?{k:tk,lv:1,v:pickV406(tk,1,x,y,ri(4)),age:0,pw:true,wa:true,h:1,sz:2}:{k:tk,ref:[x,y]}; // T516：四種原創塔樓輪廓；仍只呼叫一次 ri()，模擬 RNG 呼叫數不變，v 仍純視覺
      }
      toast((kk===1?'🏙️ 住宅摩天樓落成！':'🏙️ 商業摩天樓落成！'),'gold',x,y);sFanfare();
    }
  }
}

text.markLand:
function markLandDirty(x,y,r){
  landDirty=true;
  const x0=Math.max(0,x-r),y0=Math.max(0,y-r),x1=Math.min(N-1,x+r),y1=Math.min(N-1,y+r);
  if(!landBox)landBox={x0,y0,x1,y1};
  else{
    if(x0<landBox.x0)landBox.x0=x0;
    if(y0<landBox.y0)landBox.y0=y0;
    if(x1>landBox.x1)landBox.x1=x1;
    if(y1>landBox.y1)landBox.y1=y1;
  }
}

text.stampCov:
function stampCov(field,x,y,r,delta){
  const cat=SVC_BUDGET_CAT[field];if(cat)r=Math.max(1,Math.round(r*svcBudget[cat])); // T294：預算縮放覆蓋半徑（budget=1 時 round(r×1)=r 精確恆等，不破壞既有覆蓋/測試）
  const a=COV[field];
  for(let dy=-r;dy<=r;dy++){const ny=y+dy;if(ny<0||ny>=N)continue;
    for(let dx=-r;dx<=r;dx++){const nx=x+dx;if(nx<0||nx>=N)continue;a[idx(nx,ny)]+=delta;}}
}
